class Program {
    static func Overflow(a: int, b: int) -> int => checked(a + b)
    static func Main() -> int {
        let result = Overflow(2147483647, 1)
        return 42
    }
}

class Program {
    static func Overflow(a: int, b: int) -> int => checked(a - b)
    static func Main() -> int {
        let result = Overflow(-2147483648, 1)
        return 42
    }
}

class Program {
    static func Overflow(a: long, b: long) -> long => checked(a * b)
    static func Main() -> int {
        let result = Overflow(9223372036854775807L, 2L)
        return 42
    }
}

class Program {
    static func Overflow(a: uint, b: uint) -> uint => checked(a + b)
    static func Main() -> int {
        let result = Overflow((uint)4294967295L, (uint)1)
        return 42
    }
}

class Program {
    static func Overflow(a: ulong, b: ulong) -> ulong => checked(a - b)
    static func Main() -> int {
        let result = Overflow((ulong)0, (ulong)1)
        return 42
    }
}

class Program {
    static func Overflow(a: uint, b: uint) -> uint => checked(a * b)
    static func Main() -> int {
        let result = Overflow((uint)4294967295L, (uint)2)
        return 42
    }
}
